function mergeShifts(shifts) {
    const blocks = shifts.map(([start, end]) => [start, end]);
    let merged = true;
    while (merged) {
        merged = false;
        for (let i = 0; i < blocks.length && !merged; i++) {
            for (let j = i + 1; j < blocks.length && !merged; j++) {
                if (blocks[i][0] <= blocks[j][1] && blocks[j][0] <= blocks[i][1]) {
                    blocks[i] = [Math.min(blocks[i][0], blocks[j][0]), Math.max(blocks[i][1], blocks[j][1])];
                    blocks.splice(j, 1);
                    merged = true;
                }
            }
        }
    }
    return blocks.sort((a, b) => a[0] - b[0]);
}

function mergeShifts(shifts) {
    const sorted = shifts.map(([start, end]) => [start, end]).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    const merged = [];
    for (const [start, end] of sorted) {
        const last = merged[merged.length - 1];
        if (last !== undefined && start <= last[1])
            last[1] = Math.max(last[1], end);
        else
            merged.push([start, end]);
    }
    return merged;
}
